package com.xdownload.mobile;
import java.io.*;import java.nio.file.*;import java.security.*;import javax.crypto.*;import javax.crypto.spec.*;import java.util.*;import java.util.zip.*;
/** Local file operations; originals are never modified. */
final class FileTools{
 private static final byte[] MAGIC={'X','D','V','1'};private static final int ITER=210000;static final long VAULT_MAX=64L*1024*1024,VAULT_OVERHEAD=48;
 static byte[] readExact(InputStream in,int n)throws IOException{byte[] b=new byte[n];new DataInputStream(in).readFully(b);return b;}
 static SecretKeySpec key(char[] password,byte[] salt)throws Exception{PBEKeySpec spec=new PBEKeySpec(password,salt,ITER,256);try{byte[] raw=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(spec).getEncoded();try{return new SecretKeySpec(raw,"AES");}finally{Arrays.fill(raw,(byte)0);}}finally{spec.clearPassword();}}
 static void crypt(File input,File output,char[] password,boolean encrypt)throws Exception{
  if(password.length<8)throw new IOException("Password must have at least eight characters");if(input.getCanonicalFile().equals(output.getCanonicalFile()))throw new IOException("Choose a different output");boolean ok=false;if(encrypt&&input.length()>VAULT_MAX)throw new IOException("Vault encryption limit: 64 MiB");
  try(InputStream in=new BufferedInputStream(new FileInputStream(input));OutputStream out=new BufferedOutputStream(new FileOutputStream(output))){Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");byte[] salt,iv;if(encrypt){SecureRandom random=new SecureRandom();salt=new byte[16];iv=new byte[12];random.nextBytes(salt);random.nextBytes(iv);out.write(MAGIC);out.write(salt);out.write(iv);}else{if(!Arrays.equals(MAGIC,readExact(in,4)))throw new IOException("Not an XDownload vault file");salt=readExact(in,16);iv=readExact(in,12);if(input.length()>VAULT_MAX+VAULT_OVERHEAD)throw new IOException("Vault decryption limit: 64 MiB");}cipher.init(encrypt?Cipher.ENCRYPT_MODE:Cipher.DECRYPT_MODE,key(password,salt),new GCMParameterSpec(128,iv));cipher.updateAAD(MAGIC);cipher.updateAAD(salt);cipher.updateAAD(iv);byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new IOException("Cancelled");byte[] x=cipher.update(b,0,n);if(x!=null)out.write(x);}byte[] end=cipher.doFinal();if(end!=null)out.write(end);out.flush();ok=true;}finally{Arrays.fill(password,'\0');if(!ok)output.delete();}
 }
 static int extractZip(File archive,File destination)throws IOException{if(!destination.isDirectory()&&!destination.mkdirs())throw new IOException("Cannot create output folder");String base=destination.getCanonicalPath()+File.separator;int entries=0;long total=0;byte[] buf=new byte[65536];try(ZipInputStream in=new ZipInputStream(new BufferedInputStream(new FileInputStream(archive)))){ZipEntry e;while((e=in.getNextEntry())!=null){if(++entries>1000)throw new IOException("ZIP entry limit");File target=new File(destination,e.getName());if(!target.getCanonicalPath().startsWith(base))throw new IOException("Unsafe ZIP path");if(e.isDirectory()){if(!target.isDirectory()&&!target.mkdirs())throw new IOException("Cannot create folder");}else{File parent=target.getParentFile();if(!parent.isDirectory()&&!parent.mkdirs())throw new IOException("Cannot create folder");if(target.exists())throw new IOException("Duplicate ZIP entry");try(OutputStream out=new FileOutputStream(target)){int n;while((n=in.read(buf))!=-1){if(Thread.currentThread().isInterrupted())throw new IOException("Cancelled");total+=n;if(total>512L*1024*1024||destination.getUsableSpace()<8L*1024*1024)throw new IOException("ZIP expansion/storage limit");out.write(buf,0,n);}}}in.closeEntry();}}if(entries==0)throw new IOException("Empty or invalid ZIP");return entries;}
 static void deleteTree(File f){if(!java.nio.file.Files.isSymbolicLink(f.toPath())&&f.isDirectory()){File[] kids=f.listFiles();if(kids!=null)for(File k:kids)deleteTree(k);}f.delete();}
}